func setScanResultMeta(scanResult *models.ScanResult, report *types.Report) error {
	scanResult.ServerName = report.ArtifactName
	scanResult.Optional = nil
	if report.ArtifactType == "container_image" {
		colon := strings.LastIndex(scanResult.ServerName, ":")
		if colon < 0 || colon == len(scanResult.ServerName)-1 {
			scanResult.ServerName += ":latest"
		}
	}
	scanResult.Release = ""
	if report.Metadata.OS != nil {
		scanResult.Release = report.Metadata.OS.Name
	}

	supported := false
	for _, r := range report.Results {
		if pkg.IsTrivySupportedOS(r.Type) {
			scanResult.Family = r.Type
			supported = true
		} else if pkg.IsTrivySupportedLib(r.Type) {
			if scanResult.Family == "" {
				scanResult.Family = constant.ServerTypePseudo
			}
			supported = true
		}
		scanResult.ScannedAt = time.Now()
		scanResult.ScannedBy = "trivy"
		scanResult.ScannedVia = "trivy"
	}

	if !supported {
		return xerrors.Errorf("scanned images or libraries are not supported by Trivy. see https://aquasecurity.github.io/trivy/dev/vulnerability/detection/os/, https://aquasecurity.github.io/trivy/dev/vulnerability/detection/language/")
	}
	return nil
}
// DetectPkgCves detects OS pkg cves
// pass 2 configs
func DetectPkgCves(r *models.ScanResult, ovalCnf config.GovalDictConf, gostCnf config.GostConf, logOpts logging.LogOpts) error {
	if isPkgCvesDetactable(r) {
		if err := detectPkgsCvesWithOval(ovalCnf, r, logOpts); err != nil {
			wrapped := xerrors.Errorf("Failed to detect CVE with OVAL: %w", err)
			logging.Log.Errorf("%+v", wrapped)
			return wrapped
		}

		if err := detectPkgsCvesWithGost(gostCnf, r, logOpts); err != nil {
			wrapped := xerrors.Errorf("Failed to detect CVE with gost: %w", err)
			logging.Log.Errorf("%+v", wrapped)
			return wrapped
		}
	}

	for i, v := range r.ScannedCves {
		for j, p := range v.AffectedPackages {
			if p.NotFixedYet && p.FixState == "" {
				p.FixState = "Not fixed yet"
				r.ScannedCves[i].AffectedPackages[j] = p
			}
		}
	}

	// To keep backward compatibility
	// Newer versions use ListenPortStats,
	// but older versions of Vuls are set to ListenPorts.
	// Set ListenPorts to ListenPortStats to allow newer Vuls to report old results.
	for i, pkg := range r.Packages {
		for j, proc := range pkg.AffectedProcs {
			for _, ipPort := range proc.ListenPorts {
				ps, err := models.NewPortStat(ipPort)
				if err != nil {
					logging.Log.Warnf("Failed to parse ip:port: %s, err:%+v", ipPort, err)
					continue
				}
				r.Packages[i].AffectedProcs[j].ListenPortStats = append(
					r.Packages[i].AffectedProcs[j].ListenPortStats, *ps)
			}
		}
	}

	return nil
}

func isPkgCvesDetactable(r *models.ScanResult) bool {
	switch r.Family {
	case "":
		logging.Log.Infof("OS family is empty. Skip OVAL and gost detection")
		return false
	case constant.FreeBSD:
		logging.Log.Infof("FreeBSD is not supported by OVAL and gost package detection. Skip detection")
		return false
	case constant.Raspbian:
		logging.Log.Infof("Raspbian is not supported by OVAL and gost package detection. Skip detection")
		return false
	case constant.ServerTypePseudo:
		logging.Log.Infof("Pseudo type does not support OVAL and gost package detection. Skip detection")
		return false
	}

	if r.Release == "" {
		logging.Log.Infof("OS version is empty. Skip OVAL and gost detection")
		return false
	}
	if len(r.Packages)+len(r.SrcPackages) == 0 {
		logging.Log.Infof("Number of packages is 0. Skip OVAL and gost detection")
		return false
	}
	if isTrivyResult(r) {
		logging.Log.Infof("Scan result is from Trivy. Skip OVAL and gost detection")
		return false
	}
	return true
}

