 69			return xerrors.Errorf("scanned images or libraries are not supported by Trivy. see https://aquasecurity.github.io/trivy/dev/vulnerability/detection/os/, https://aquasecurity.github.io/trivy/dev/vulnerability/detection/language/")
 70		}
 71		return nil
 72	}
207	// DetectPkgCves detects OS pkg cves
208	// pass 2 configs
209	func DetectPkgCves(r *models.ScanResult, ovalCnf config.GovalDictConf, gostCnf config.GostConf, logOpts logging.LogOpts) error {
210		if isPkgCvesDetactable(r) {
211			if err := detectPkgsCvesWithOval(ovalCnf, r, logOpts); err != nil {
212				wrapped := xerrors.Errorf("Failed to detect CVE with OVAL: %w", err)
213				logging.Log.Errorf("%+v", wrapped)
214				return wrapped
215			}
216	
217			if err := detectPkgsCvesWithGost(gostCnf, r, logOpts); err != nil {
218				wrapped := xerrors.Errorf("Failed to detect CVE with gost: %w", err)
219				logging.Log.Errorf("%+v", wrapped)
220				return wrapped
221			}
222		}
223	
224		for i, v := range r.ScannedCves {
225			for j, p := range v.AffectedPackages {
226				if p.NotFixedYet && p.FixState == "" {
227					p.FixState = "Not fixed yet"
228					r.ScannedCves[i].AffectedPackages[j] = p
229				}
230			}
231		}
232	
233		// To keep backward compatibility
234		// Newer versions use ListenPortStats,
235		// but older versions of Vuls are set to ListenPorts.
236		// Set ListenPorts to ListenPortStats to allow newer Vuls to report old results.
237		for i, pkg := range r.Packages {
238			for j, proc := range pkg.AffectedProcs {
239				for _, ipPort := range proc.ListenPorts {
240					ps, err := models.NewPortStat(ipPort)
241					if err != nil {
242						logging.Log.Warnf("Failed to parse ip:port: %s, err:%+v", ipPort, err)
243						continue
244					}
245					r.Packages[i].AffectedProcs[j].ListenPortStats = append(
246						r.Packages[i].AffectedProcs[j].ListenPortStats, *ps)
247				}
248			}
249		}
250	
251		return nil
252	}
