254	func isPkgCvesDetactable(r *models.ScanResult) bool {
255		switch r.Family {
256		case "":
257			logging.Log.Infof("OS family is empty. Skip OVAL and gost detection")
258			return false
259		case constant.FreeBSD:
260			logging.Log.Infof("FreeBSD is not supported by OVAL and gost package detection. Skip detection")
261			return false
262		case constant.Raspbian:
263			logging.Log.Infof("Raspbian is not supported by OVAL and gost package detection. Skip detection")
264			return false
265		case constant.ServerTypePseudo:
266			logging.Log.Infof("Pseudo type does not support OVAL and gost package detection. Skip detection")
267			return false
268		}
269	
270		if r.Release == "" {
271			logging.Log.Infof("OS version is empty. Skip OVAL and gost detection")
272			return false
273		}
274		if len(r.Packages)+len(r.SrcPackages) == 0 {
275			logging.Log.Infof("Number of packages is 0. Skip OVAL and gost detection")
276			return false
277		}
278		if isTrivyResult(r) {
279			logging.Log.Infof("Scan result is from Trivy. Skip OVAL and gost detection")
280			return false
281		}
282		return true
283	}
